-- Phase 536 tests (UNION-8: 43 shared functions carry the merged text). TEST DATABASE ONLY (a local throwaway Postgres built from the owner paste chain, tests/sql/run_all_union.sh). Prints PASS / FAIL per check.
-- Test users and items are neutral test_* ids. Run on the final database (needs phase539 for the audit, so it checks the md5 itself).
\set ON_ERROR_STOP off
\set o '00000000-0000-0000-0000-00000000f536'
create schema if not exists t536;
create table if not exists t536.res (name text, ok boolean);
truncate t536.res;
create or replace function t536.chk(p_name text, p_ok boolean) returns void language plpgsql as $$
begin insert into t536.res values (p_name, coalesce(p_ok, false)); raise notice '% %', case when coalesce(p_ok, false) then 'PASS' else 'FAIL' end, p_name; end $$;
create or replace function t536.def(p_sig text) returns text language sql as $$ select pg_get_functiondef(p_sig::regprocedure) $$;
create or replace function t536.has(p_sig text, p_text text) returns boolean language sql as $$ select position(p_text in pg_get_functiondef(p_sig::regprocedure)) > 0 $$;

\echo == T1 every function of this file has the merged text (the md5 is recorded by phase539; this suite runs on the final database)
